mapper.insert:
INSERT INTO user_operate_log (
    user_id, operate_type, stock_code, change_money, fund_direction, after_money,
    game_date, game_time, remark, create_time
) VALUES (
    #{userId}, #{operateType}, #{stockCode}, #{changeMoney}, #{fundDirection}, #{afterMoney},
    #{gameDate}, #{gameTime}, #{remark}, #{createTime}
)

mapper.select:
SELECT id, user_id, operate_type, stock_code, change_money, fund_direction, after_money,
       game_date, game_time, remark, create_time
FROM user_operate_log
WHERE user_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{limit}
